"use strict";(self.webpackChunk_otw_web_docusaurus=self.webpackChunk_otw_web_docusaurus||[]).push([[5265],{7931(e){e.exports=JSON.parse('{"title":"\ub3c4\uc6c0\ub418\ub294 \uc624\ub958 \uba54\uc138\uc9c0 \uc791\uc131\ud558\uae30","date":"2025-05-07","coverUrl":"/kudzu-based-bench/assets/notion/b0824a99875949c5.png","html":"<h2 data-notion-block-id=\\"1e6e548d-8a8e-8003-978c-c2f1857bff79\\" id=\\"1e6e548d-8a8e-8003-978c-c2f1857bff79\\">\ub3c4\uc6c0\ub418\ub294 \uc624\ub958 \uba54\uc138\uc9c0 \uc791\uc131\ud558\uae30</h2><a href=\\"https://piccalil.li/blog/how-to-write-error-messages-that-actually-help-users-rather-than-frustrate-them/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://piccalil.li/blog/how-to-write-error-messages-that-actually-help-users-rather-than-frustrate-them/</a><p data-notion-block-id=\\"1e6e548d-8a8e-801d-859e-f37882aa9258\\">\uc5ec\ub7ec\uac00\uc9c0 \ud301\uc744 \ud1b5\ud574\uc11c \uc0ac\uc6a9\uc790\uac00 \uc624\ub958\uc5d0 \ub300\ucc98\ud560 \uc218 \uc788\ub3c4\ub85d \ub3d5\ub294 \ub3c4\uc6c0\uc774 \ub418\ub294 \uc624\ub958 \uba54\uc138\uc9c0\ub97c \uc791\uc131\ud558\ub3c4\ub85d \ub3d5\ub294 \uae00\uc785\ub2c8\ub2e4. \ub354 \ubc94\uc6a9\uc801\uc774\uace0, \uc624\ub958 \uba54\uc138\uc9c0 \ub9d0\uace0\ub3c4 \ub2e4\ub978 UI\uc640 \ud569\uccd0\uc11c \uc5b4\ub5bb\uac8c \uc791\uc131\ud574\uc57c \ud558\ub294\uc9c0 \uac00\uc774\ub4dc\ud558\ub294 \uae00\uc740 <a href=\\"https://www.smashingmagazine.com/2022/08/error-messages-ux-design/\\">Designing Better Error Messages UX</a>\ub97c \ucc38\uace0\ud558\uc2dc\uace0, \ub2e4\ub978 \ud68c\uc0ac\uc758 \uac83\uc744 \ucc38\uace0\ud558\ub824\uba74, <a href=\\"https://spotify.design/article/the-art-of-the-error-message\\">Spotify\uc758 \uae00</a>\uc774\ub098 <a href=\\"https://toss.tech/article/21021\\">\ud1a0\uc2a4\uc758 \uae00</a>\uc744 \ucc38\uace0\ud558\uc138\uc694.</p><h2 data-notion-block-id=\\"1e9e548d-8a8e-8011-9493-d59dd4180932\\" id=\\"1e9e548d-8a8e-8011-9493-d59dd4180932\\">\ub9ac\uc561\ud2b8 \ucef4\ud3ec\ub10c\ud2b8 \ub354 \uc798 \ub9cc\ub4e4\uae30</h2><a href=\\"https://www.youtube.com/watch?v=SlW2FFBQjt8\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.youtube.com/watch?v=SlW2FFBQjt8</a><p data-notion-block-id=\\"1e9e548d-8a8e-804c-9c2e-fd2b9af17de6\\">\uc815\ub9d0 \ub9ac\uc561\ud2b8 \ucef4\ud3ec\ub10c\ud2b8\ub97c \uc798 \ub9cc\ub4e4\uae30 \uc704\ud55c \ubaa8\ub4e0 \uac83\uc744 \ub2e4\ub8e8\uc9c0\ub294 \uc54a\uc9c0\ub9cc, \uae30\ubcf8 \ub9ac\uc561\ud2b8\ub97c \ubc30\uc6b4 \uc0c1\ud0dc\uc5d0\uc11c, \uae30\ubcf8 \ub514\uc790\uc778 \ud328\ud134(ex. button, input, \u2026)\uc744 \ub354 \uc798 \ub9cc\ub4e4\uae30 \uc704\ud55c \ud301\uc744 \uc18c\uac1c\ud558\ub294 \uc601\uc0c1\uc785\ub2c8\ub2e4. \uc5ec\uae30\uc11c \ub354 \ub098\uc544\uac00\uc11c <a href=\\"https://ones-to-watch.ethansup.net/news/post/f51019e1-e38c-4b60-a636-aab2334f6e8b#db3ef69e-93d7-422a-a3e0-d5816a79be50\\">\ucef4\ud3ec\ub10c\ud2b8\ub97c Composition\uc73c\ub85c \uad6c\uc131\ud558\ub290\ub0d0, slot \ubc29\uc2dd\uc73c\ub85c \uad6c\uc131\ud558\ub290\ub0d0</a>\uc640 \uac19\uc740 \uc5ec\ub7ec \ub514\uc790\uc778\uc2dc\uc2a4\ud15c\uc5d0 \uc801\uc6a9\ud558\uae30 \uc804 \ucef4\ud3ec\ub10c\ud2b8\ub97c \ub9cc\ub4e4 \ub54c\uc758 \uad6c\uc0c1\uc744 \ud560 \uc218\ub3c4 \uc788\uc9c0\ub9cc, \uc18c\uac1c\ud558\ub294 \ud301\ub3c4 \ud6cc\ub96d\ud569\ub2c8\ub2e4.</p><a href=\\"https://julesblom.com/writing/parent-owners-context\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://julesblom.com/writing/parent-owners-context</a><p data-notion-block-id=\\"1e6e548d-8a8e-8039-a608-e77951257f87\\"><code>&#x3C;Context.Provider></code>\uc758 \uc7ac\ub80c\ub354\ub9c1\uc744 \ub9c9\uae30 \uc704\ud574 \ubd80\ubaa8 \ud2b8\ub9ac\uc640 \uc18c\uc720\uc790 \ud2b8\ub9ac \uac1c\ub150\uc744 \ub3c4\uc785\ud574 \uc18c\uc720\uc790 \ud2b8\ub9ac\ub97c \ucd5c\uc801\ud654\ud558\ub294 \uae00\uc785\ub2c8\ub2e4. \ucef4\ud3ec\ub10c\ud2b8\ub85c \uac10\uc2f8\uc11c \ucd5c\uc801\ud654\ud558\ub294 \ubc29\uc2dd\uc740 \uacfc\uac70\uc5d0 \ub9ce\uc774 \ub098\uc654\uc9c0\ub9cc(ex. <a href=\\"https://julesblom.com/writing/parent-owners-context\\">Tkdodo\ub2d8\uc758 memoization\ubc29\uc2dd \uc18c\uac1c</a>), \ubd80\ubaa8 \ud2b8\ub9ac\uc640 \uc18c\uc720\uc790 \ud2b8\ub9ac \uac1c\ub150\uc744 \ub3c4\uc785\ud558\ub294 \uac83\uc740 \uc2e0\uc120\ud558\ub124\uc694.</p><h2 data-notion-block-id=\\"1e6e548d-8a8e-8022-888c-daeacf50df59\\" id=\\"1e6e548d-8a8e-8022-888c-daeacf50df59\\">useEffect\uc758 \ub3d9\uc791 \uc54c\uc544\ubcf4\uae30</h2><a href=\\"https://frontendmasters.com/blog/react-internals-which-useeffect-runs-first/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://frontendmasters.com/blog/react-internals-which-useeffect-runs-first/</a><p data-notion-block-id=\\"1e9e548d-8a8e-8048-bd89-cc6c709aead1\\">React\uc758 \ub80c\ub354\ub9c1 \uacfc\uc815\uacfc \uc5f0\uacb0\uc9c0\uc5b4\uc11c useEffect \uc2e4\ud589 \uc21c\uc11c\uac00 \uc5b4\ub5bb\uac8c \uc815\ud574\uc9c0\ub294\uc9c0 \uc18c\uac1c\ud558\ub294 \uae00\uc785\ub2c8\ub2e4. \ub354 \uc790\uc138\ud55c \ucf54\ub4dc\uc640 \uc124\uba85\uc744 \ubcf4\ub824\uba74, <a href=\\"https://jser.dev/2023-07-08-how-does-useeffect-work\\">JSer\uc758 useEffect Deep dive \uae00</a>\uc744 \ubcf4\uc2dc\uae38 \ucd94\ucc9c\ub4dc\ub9bd\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"1e9e548d-8a8e-8008-8f66-c3e8d89ca342\\" id=\\"1e9e548d-8a8e-8008-8f66-c3e8d89ca342\\">\uc560\ub2c8\uba54\uc774\uc158\uc744 \ub354 \uc88b\uac8c</h2><a href=\\"https://emilkowal.ski/ui/good-vs-great-animations\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://emilkowal.ski/ui/good-vs-great-animations</a><p data-notion-block-id=\\"1e6e548d-8a8e-8050-9a56-f1eb3e3100c4\\">\uac04\ub2e8\ud55c \uc560\ub2c8\uba54\uc774\uc158\uc744 \ub123\ub294 \uac83\ub9cc\uc73c\ub85c UI\uac00 \uba4b\uc838\ubcf4\uc77c \uc218 \uc788\uc9c0\ub9cc, \ub354 \uba4b\uc9c0\uac8c, \ub354 \uc88b\uac8c \ub9cc\ub4e4\uae30 \uc704\ud55c \ud301\uc744 \uc18c\uac1c\ud558\ub294 \uae00\uc785\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"1e9e548d-8a8e-8086-9f15-ff8077cd10ea\\" id=\\"1e9e548d-8a8e-8086-9f15-ff8077cd10ea\\">Webview\ub97c \ub124\uc774\ud2f0\ube0c\ucc98\ub7fc \ub9cc\ub4e4\uae30</h2><a href=\\"https://shopify.engineering/mobilebridge-native-webviews\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://shopify.engineering/mobilebridge-native-webviews</a><p data-notion-block-id=\\"1e9e548d-8a8e-803e-b0d3-d2e55227c8f2\\">Shopify\uc758 Webview\ub97c \ub124\uc774\ud2f0\ube0c\ub85c \ub9cc\ub4e4\uae30 \uc704\ud574 \ud55c \ub178\ub825\ub4e4\uacfc \ud301\uc744 \uc18c\uac1c\ud558\ub294 \uae00\uc785\ub2c8\ub2e4. cached-webview \ub77c\uc774\ube0c\ub7ec\ub9ac\uac19\uc774 \ubc29\ubc95\ub860\ub9cc \uc81c\uc2dc\ud55c \uacbd\uc6b0\ub3c4 \uc788\uc9c0\ub9cc, \uc5ec\ub7ec \ud301\uc740 \uc6f9\ubdf0\ub97c \uac1c\ubc1c\ud558\ub294\ub370\uc5d0 \uc88b\uc740 \ud301\uc774 \ub429\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"1e9e548d-8a8e-8006-bfd3-c76b6458b66e\\" id=\\"1e9e548d-8a8e-8006-bfd3-c76b6458b66e\\"><code>\\"use client\\"</code>\uac00 \ud558\ub294 \uc77c</h2><a href=\\"https://overreacted.io/what-does-use-client-do/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://overreacted.io/what-does-use-client-do/</a><p data-notion-block-id=\\"1e9e548d-8a8e-802c-a4bc-fa48c19f57ae\\"><code>\\"use server\\"</code>\uc640 <code>\\"use client\\"</code>\uac00 \uc5b4\ub5bb\uac8c \ub3d9\uc791\ud558\ub294\uc9c0\ub97c \uac04\ub2e8\ud558\uac8c \uc18c\uac1c\ud558\ub294 \uae00\uc785\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"1e9e548d-8a8e-808d-8e7e-e5e8a802e6ad\\" id=\\"1e9e548d-8a8e-808d-8e7e-e5e8a802e6ad\\">\ub099\uad00\uc801 \uc5c5\ub370\uc774\ud2b8\uc640 \ub3d9\uc2dc \uc694\uccad</h2><a href=\\"https://tkdodo.eu/blog/concurrent-optimistic-updates-in-react-query\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://tkdodo.eu/blog/concurrent-optimistic-updates-in-react-query</a><p data-notion-block-id=\\"1e6e548d-8a8e-8050-a852-cc5d4d313af3\\">\ub099\uad00\uc801 \uc5c5\ub370\uc774\ud2b8\ub294 \uc989\uc2dc UI\ub97c \uc5c5\ub370\uc774\ud2b8\ud574\uc11c \uc0ac\uc6a9\uc790\uac00 \ube60\ub974\ub2e4\uace0 \uc0dd\uac01\ud558\uac8c \ud560 \uc218 \uc788\uc9c0\ub9cc, \uac19\uc740 \uc5c5\ub370\uc774\ud2b8\uac00 \uc5ec\ub7ec\ubc88 \uc788\uc744 \uacbd\uc6b0\uc758 \ub099\uad00\uc801 \uc5c5\ub370\uc774\ud2b8\uc5d0\uc11c\ub294 race condition\uacfc \uc774\uc0c1\ud55c UX\uac00 \uc0dd\uae38 \uc218\ub3c4 \uc788\uc2b5\ub2c8\ub2e4. \uc774\ub97c \uc5b4\ub5bb\uac8c \ud574\uacb0\ud574\uc57c \ud560\uc9c0 \uc18c\uac1c\ud558\ub294 \uae00\uc785\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"1e6e548d-8a8e-8037-ab6b-c559dc2c3b41\\" id=\\"1e6e548d-8a8e-8037-ab6b-c559dc2c3b41\\">RSC\ub294 Promise\ub97c \uc9c1\ub82c\ud654 \ud55c\ub2e4, \uc5b4\ub5bb\uac8c \uac00\ub2a5\ud55c\uac78\uae4c?</h2><a href=\\"https://twofoldframework.com/blog/you-can-serialize-a-promise-in-react\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://twofoldframework.com/blog/you-can-serialize-a-promise-in-react</a><p data-notion-block-id=\\"1e9e548d-8a8e-807c-bb1a-c701452dfa9a\\"><code>JSON.stringify</code>\uc5d0\uc11c\ub294 \ubd88\uac00\ub2a5\ud55c Promise \uc9c1\ub82c\ud654\ub97c React\uc5d0\uc11c\ub294 \uc5b4\ub5bb\uac8c \ud574\uacb0\ud588\ub294\uc9c0 \ubc11\ubc14\ub2e5\ubd80\ud130 \uad6c\ud604\ud558\uba74\uc11c \uc54c\uc544\ubcf4\ub294 \uae00\uc785\ub2c8\ub2e4. \uc774\uc678\uc5d0\ub3c4 RSC\uc5d0\uc11c\ub294 Map, Set..\uacfc \uac19\uc740 \uc790\ub8cc\uad6c\uc870\ub3c4 \uc9c1\ub82c\ud654 \uac00\ub2a5\ud558\ub2e4\ub2c8 \uc54c\uc544\ub46c\uc57c\uaca0\ub124\uc694. </p><h2 data-notion-block-id=\\"1e9e548d-8a8e-8055-aa8b-c3f08dc2b280\\" id=\\"1e9e548d-8a8e-8055-aa8b-c3f08dc2b280\\">Lexical Environment \uc2dc\uac01\uc801\uc73c\ub85c \uc774\ud574\ud558\uae30</h2><a href=\\"https://piccalil.li/blog/javascript-when-is-this/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://piccalil.li/blog/javascript-when-is-this/</a><p data-notion-block-id=\\"1e9e548d-8a8e-806b-a255-ffdc29f5b749\\">JS\uc758 \ub3d9\uc791\uc758 \uc911\uc2ec\uc778 Lexical Environment\ub97c \ucf54\ub4dc\uc640 \ud568\uaed8 \uc88b\uc740 \ub2e4\uc774\uc5b4\uadf8\ub7a8\uc73c\ub85c \uc774\ud574\ud558\uae30 \uc27d\uac8c \ub3d5\ub294 \uae00\uc785\ub2c8\ub2e4. <a href=\\"https://javascript.info/closure\\">Closure\ub97c \uc18c\uac1c\ud558\ub294 javascript.info\uae00</a>\uacfc \uac19\uc774 \ubcf4\uba74 \uc88b\uc2b5\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"1eae548d-8a8e-803c-8889-e0efbd238869\\" id=\\"1eae548d-8a8e-803c-8889-e0efbd238869\\">\ub124\ud2b8\uc6cc\ud06c\uac00 \ubd88\uc548\uc815\ud560 \ub54c\ub97c \ub300\ube44\ud55c \uc774\ubbf8\uc9c0 \uc5c5\ub85c\ub4dc \uad6c\ud604</h2><a href=\\"https://www.smashingmagazine.com/2025/04/building-offline-friendly-image-upload-system/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.smashingmagazine.com/2025/04/building-offline-friendly-image-upload-system/</a><p data-notion-block-id=\\"1e9e548d-8a8e-8047-b312-e1892fb916d5\\">IndexedDB\uc640 Service Worker\ub97c \uc0ac\uc6a9\ud574\uc11c \ub124\ud2b8\uc6cc\ud06c\uac00 \ubd88\uc548\uc815\ud560 \uacbd\uc6b0 \ub85c\uceec\uc5d0 \uc800\uc7a5\ud558\uace0 \ub098\uc911\uc5d0 \uc5c5\ub85c\ub4dc\ud558\ub294 \ub85c\uc9c1\uc744 \uad6c\ud604\ud574\ubcf4\ub294 \uae00\uc785\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"1e9e548d-8a8e-8068-807e-fef2359b2444\\" id=\\"1e9e548d-8a8e-8068-807e-fef2359b2444\\">\uc8fc\ubaa9\ud560\ub9cc\ud55c \uce5c\uad6c\ub4e4</h2><a href=\\"https://webkit.org/blog/16831/line-height-units/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://webkit.org/blog/16831/line-height-units/</a><p data-notion-block-id=\\"1e9e548d-8a8e-8030-a0ae-fcd0c67dd533\\">2023\ub144 Baseline\uc73c\ub85c \ub4e4\uc5b4\uc640 \ubaa8\ub358 \ube0c\ub77c\uc6b0\uc800\uc5d0\uc11c \ubaa8\ub450 \uad6c\ud604\ub41c <code>line-height</code> \uae30\ubc18 <code>lh</code>\ub2e8\uc704\uc5d0 \ub300\ud574 \uc18c\uac1c\ud558\ub294 \uae00\uc785\ub2c8\ub2e4.</p><a href=\\"https://v8.dev/blog/explicit-compile-hints\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://v8.dev/blog/explicit-compile-hints</a><p data-notion-block-id=\\"1e9e548d-8a8e-80ba-9185-d77969f3d7ff\\">V8\uc5d0\uc11c \uc2e4\ud5d8\uc801\uc73c\ub85c JS\uc5d0\uc11c \uba85\uc2dc\uc801\uc73c\ub85c \ud568\uc218\ub97c \ubc14\ub85c \ucef4\ud30c\uc77c\ud560 \uac83\uc778\uc9c0 \uc774\ud6c4\uc5d0 \ucef4\ud30c\uc77c\ud560 \uac83\uc778\uc9c0 \ud78c\ud2b8\ub97c \uc81c\uacf5\ud560 \uc218 \uc788\ub3c4\ub85d \ud558\ub294 \uae30\ub2a5\uc744 \ucd94\uac00\ud588\ub2e4\ub294 \uae00\uc785\ub2c8\ub2e4. \ubcf4\uae30\uc5d0 \ud765\ubbf8\ub85c\uc6b4 \uae00\uc774\uc9c0\ub9cc, \uccad\ud06c\ub2e8\uc704\ub85c \ucef4\ud30c\uc77c\ud558\uc9c0 \uc54a\ub294 \uc774\uc0c1 \ub9ce\uc774 \ub9c8\uc8fc\uce58\uae30 \ud798\ub4e0 \uae30\ub2a5\uc778 \uac83\ucc98\ub7fc \ubcf4\uc785\ub2c8\ub2e4.</p><a href=\\"https://www.youtube.com/watch?v=4bbU1gA2aSk\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.youtube.com/watch?v=4bbU1gA2aSk</a><p data-notion-block-id=\\"1e9e548d-8a8e-8069-9330-c909f50ce7f7\\">Dockerfile\uac19\uc740 \ucee8\ud14c\uc774\ub108 \uc120\uc5b8 \ud30c\uc77c\uc744 \uae30\ubc18\uc73c\ub85c WASM \ubc14\uc774\ub108\ub9ac\ub85c \ub9cc\ub4e4\uc5b4\uc8fc\ub294 \uc5b4\ud50c\ub9ac\ucf00\uc774\uc158\uc778 Boxer\ub97c \uc18c\uac1c\ud558\ub294 \uc601\uc0c1\uc785\ub2c8\ub2e4.</p><a href=\\"https://deno.com/blog/add-jsr-with-pnpm-yarn\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://deno.com/blog/add-jsr-with-pnpm-yarn</a><p data-notion-block-id=\\"1e9e548d-8a8e-8042-a56f-d0c3c2b2d238\\">pnpm\uacfc yarn\uc774 JSR \ud328\ud0a4\uc9c0 \uc124\uce58\ub97c \uc9c0\uc6d0\ud55c\ub2e4\ub294 \uc18c\uc2dd\uc785\ub2c8\ub2e4.</p>"}')}}]);